import SwiftUI

/// An AI provider's mark (`BrandLogos.swift`, generated by scripts/brandlogos.py): Claude in its brand
/// colour, OpenAI in `text1` so it reads in light and dark. Only ever shown next to the provider's name.
struct BrandLogoView: View {
    let logo: BrandLogo
    var size: CGFloat = 28

    var body: some View {
        Canvas { context, canvas in
            let scale = min(canvas.width, canvas.height) / 24
            context.fill(Path(logo.path).applying(CGAffineTransform(scaleX: scale, y: scale)), with: .color(logo.color))
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}

extension BrandLogo {
    var color: Color { brandColor.map { Color(Theme.rgb($0)) } ?? Color(Theme.text1) }

    /// The mark on the 24 grid, parsed once.
    var path: CGPath { Self.parsed[self] ?? CGMutablePath() }

    private static let parsed = Dictionary(uniqueKeysWithValues: allCases.map { ($0, SVGPath.parse($0.pathData)) })
}
